package com.jenga.aeternalis.ui;
import com.jenga.aeternalis.network.*;
import com.jenga.aeternalis.distributed.*;
import com.jenga.aeternalis.app.*;
import javafx.application.Platform;
import javafx.animation.*;
import javafx.util.Duration;
import javafx.stage.*;
import javafx.scene.*;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.scene.chart.*;
import javafx.geometry.Insets;
import java.nio.file.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.function.*;
/** Native session management, computers, statistics and disk-backed export, sharing the studio theme/icon. */
public final class NetworkManagerWindow implements AutoCloseable {
    private final Stage window=new Stage();private final TabPane tabs=new TabPane();private final NetworkService service=NetworkService.instance();
    private final TextField bind=new TextField("0.0.0.0"),host=new TextField("127.0.0.1"),port=new TextField("5050"),threshold=new TextField("60"),timeout=new TextField("600"),exportWidth=new TextField("4096"),exportHeight=new TextField("4096");private final PasswordField token=new PasswordField();
    private final Spinner<Integer> threads=new Spinner<>(1,256,Math.min(256,Runtime.getRuntime().availableProcessors())),tileSize=new Spinner<>(16,256,64,16);private final ComboBox<NetworkService.Mode> mode=new ComboBox<>();private final CheckBox local=new CheckBox("Master also computes tiles"),overlay=new CheckBox("Show tile ownership overlay on the main image");
    private final Label notice=new Label(),masterText=new Label(),workerText=new Label(),exportStatus=new Label("Final PNG is published only after all layers are complete.");private final TextArea computers=new TextArea(),statistics=new TextArea();private final Map<String,XYChart.Series<Number,Number>> series=new HashMap<>();private final LineChart<Number,Number> chart=new LineChart<>(new NumberAxis(),new NumberAxis());
    private final ExecutorService operations=Executors.newVirtualThreadPerTaskExecutor();private final Timeline timer=new Timeline(new KeyFrame(Duration.millis(500),e->refresh()));private final AtomicBoolean exportCancelled=new AtomicBoolean(),exporting=new AtomicBoolean();private final AtomicReference<String> exportMessage=new AtomicReference<>("Final PNG is published only after all layers are complete.");private final Supplier<StudioDocument> document;private final Runnable cancelMain,renderMain;private long lastChart;private final long opened=System.nanoTime();
    public NetworkManagerWindow(Stage owner,Supplier<StudioDocument> document,Runnable cancelMain,Runnable renderMain){
        this.document=document;this.cancelMain=cancelMain;this.renderMain=renderMain;window.initOwner(owner);window.setTitle("Aeternalis · Network rendering");mode.getItems().setAll(NetworkService.Mode.values());mode.setValue(service.mode());threshold.setText(""+service.threshold());tileSize.getValueFactory().setValue(service.tileSize());local.setSelected(service.master()==null||service.master().localEnabled());overlay.setSelected(service.master()!=null&&service.master().overlay());
        for(Label label:List.of(notice,masterText,workerText,exportStatus))label.setWrapText(true);computers.setEditable(false);statistics.setEditable(false);computers.setPrefRowCount(16);statistics.setPrefRowCount(12);
        Label warning=new Label("Private trusted LAN only. Do not forward this port to the public internet. The optional session token controls admission; traffic is not encrypted. Enter the Master’s LAN IP on Workers; no shared folder is needed.");warning.setWrapText(true);warning.setMinHeight(Region.USE_PREF_SIZE);
        VBox master=box(new Label("Master server"),new Label("Bind address (0.0.0.0 accepts LAN connections)"),bind,new Label("Port (shared by Master and Worker settings)"),port,new Label("Session access token (optional)"),token,new Label("Local/Worker compute threads · applies when starting or connecting"),threads,new HBox(8,button("Start Master",this::startMaster),button("Stop / disconnect",this::disconnect)),masterText,button("Render current viewport",()->{try{saveSettings();renderMain.run();}catch(Exception ex){notice.setText(ex.getMessage());}}));
        TextField workerPort=new TextField();workerPort.textProperty().bindBidirectional(port.textProperty());PasswordField workerToken=new PasswordField();workerToken.textProperty().bindBidirectional(token.textProperty());Spinner<Integer> workerThreads=new Spinner<>(1,256,threads.getValue());workerThreads.getValueFactory().valueProperty().bindBidirectional(threads.getValueFactory().valueProperty());
        VBox worker=box(new Label("Connect this computer as a Worker"),new Label("Master IP / hostname"),host,new Label("Master port"),workerPort,new Label("Session token"),workerToken,new Label("Compute threads"),workerThreads,new HBox(8,button("Connect Worker",this::connect),button("Disconnect",this::disconnect)),workerText);
        VBox settings=box(new Label("Rendering selection"),mode,new Label("Automatic: use network when estimated local time exceeds seconds"),threshold,new Label("Network tile edge (16–256 pixels)"),tileSize,new Label("Maximum task lease seconds (1–3600); disconnected tasks are requeued sooner"),timeout,local,overlay,button("Apply settings",()->{try{saveSettings();notice.setText("Network settings applied. Use Render current viewport to force a new pass.");}catch(Exception ex){notice.setText(ex.getMessage());}}));
        chart.setTitle("Average accepted samples / second by computer");chart.setAnimated(false);chart.setCreateSymbols(false);chart.setMinHeight(220);chart.setPrefHeight(260);VBox stats=box(statistics,chart);
        Button export=button("Render high-resolution PNG…",()->export());Button cancelExport=button("Cancel export",()->exportCancelled.set(true));VBox exportPane=box(new Label("Disk-backed image export · all visible layers and palettes"),new Label("Width"),exportWidth,new Label("Height"),exportHeight,new HBox(8,export,cancelExport),exportStatus,new Label("Requires scratch disk space for numerical tiles and ARGB layers. Frames remain local to the Master."));
        tabs.getTabs().addAll(tab("Master",master),tab("Worker",worker),tab("Settings",settings),tab("Computers",box(computers)),tab("Statistics",stats),tab("Image export",exportPane));tabs.setTabClosingPolicy(TabPane.TabClosingPolicy.UNAVAILABLE);
        VBox root=box(EditorialArt.heading("Network rendering","One observatory · shared computation"),warning,tabs,notice);VBox.setVgrow(tabs,Priority.ALWAYS);Scene scene=new Scene(root,920,760);Theme.apply(scene);window.setScene(scene);WindowBounds.install(window,owner);window.setOnHidden(e->timer.stop());window.setOnCloseRequest(e->{exportCancelled.set(true);});
    }
    private static VBox box(Node... nodes){VBox b=new VBox(10,nodes);b.setPadding(new Insets(14));return b;}
    private static Tab tab(String title,Node body){ScrollPane scroll=new ScrollPane(body);scroll.setFitToWidth(true);return new Tab(title,scroll);}
    private static Button button(String title,Runnable action){Button b=new Button(title);b.setOnAction(e->action.run());return b;}
    public void show(int tab){tabs.getSelectionModel().select(tab);window.show();window.toFront();refresh();timer.setCycleCount(Animation.INDEFINITE);timer.play();}
    private void saveSettings(){service.settings(mode.getValue(),Double.parseDouble(threshold.getText().trim()),tileSize.getValue());if(service.master()!=null){service.master().localEnabled(local.isSelected());service.master().overlay(overlay.isSelected());service.master().timeout(Long.parseLong(timeout.getText().trim())*1000);}}
    private void startMaster(){try{cancelMain.run();saveSettings();String address=bind.getText().trim(),secret=token.getText();int p=Integer.parseInt(port.getText().trim()),n=threads.getValue();operations.submit(()->{try{service.host(address,p,secret,n);Platform.runLater(()->{port.setText(""+service.master().port());saveSettings();refresh();});}catch(Exception ex){message(ex);}});}catch(Exception ex){message(ex);}}
    private void connect(){try{cancelMain.run();saveSettings();String address=host.getText().trim(),secret=token.getText();int p=Integer.parseInt(port.getText().trim()),n=threads.getValue();operations.submit(()->{try{service.connect(address,p,secret,n);Platform.runLater(this::refresh);}catch(Exception ex){message(ex);}});}catch(Exception ex){message(ex);}}
    private void disconnect(){cancelMain.run();operations.submit(()->{service.close();Platform.runLater(this::refresh);});}
    private void message(Exception e){Platform.runLater(()->notice.setText(e.getMessage()));}
    private void export(){if(exporting.get()){exportStatus.setText("An image export is already running. Finish or cancel it first.");return;}try{
        saveSettings();int w=Integer.parseInt(exportWidth.getText().trim()),h=Integer.parseInt(exportHeight.getText().trim());StudioDocument snapshot=document.get();FileChooser chooser=new FileChooser();chooser.setTitle("Render image to PNG");chooser.getExtensionFilters().add(new FileChooser.ExtensionFilter("PNG image","*.png"));chooser.setInitialFileName("aeternalis-network.png");var output=chooser.showSaveDialog(window);if(output==null)return;if(!exporting.compareAndSet(false,true))return;cancelMain.run();exportCancelled.set(false);exportMessage.set("Preparing disk-backed export…");exportStatus.setText(exportMessage.get());
        operations.submit(()->{try{DiskPngExport.render(snapshot,w,h,output.toPath(),exportCancelled,exportMessage::set);}catch(CancellationException ex){exportMessage.set("Export cancelled; no incomplete image was published.");}catch(Exception ex){exportMessage.set("Export failed: "+ex.getMessage());}finally{exporting.set(false);}});
    }catch(Exception ex){message(ex);}}
    private void refresh(){
        exportStatus.setText(exportMessage.get());
        MasterServer server=service.master();WorkerClient client=service.worker();notice.setText(service.notice());
        if(server==null){masterText.setText("Master is stopped.");computers.setText("No Master session.");statistics.setText("No render statistics yet.");}
        else{
            var list=server.computers();int cpu=(server.localEnabled()?server.localThreads():0)+list.stream().filter(c->c.slots()>0).mapToInt(MasterServer.Computer::slots).sum();DistributedJob job=server.job();
            masterText.setText("Role: Master\nBound address: "+server.bindAddress()+"\nLAN addresses: "+addresses()+"\nPort: "+server.port()+"\nConnected Workers: "+server.workerCount()+" · total computers: "+(server.workerCount()+1)+"\nAvailable configured CPU threads: "+cpu+"\nRendering mode: "+service.mode()+"\n"+(job==null?"Awaiting render":job.done()+" / "+job.total+" tiles · "+String.format(Locale.ROOT,"%.2f%%",100.*job.done()/job.total)+" · generation "+job.generation()+" · "+job.context().plan.mode()));
            StringBuilder text=new StringBuilder("COMPUTER | IP | STATUS | CORES / THREADS | MEMORY | TILES | AVG TILE | TX / RX\nMaster | local "+server.localEnabled()+" | "+Runtime.getRuntime().availableProcessors()+" / "+server.localThreads()+"\n");for(var c:list)text.append(c.name()).append(" [").append(c.id(),0,8).append("] | ").append(c.address()).append(" | ").append(c.slots()>0?"Connected "+c.slots()+" slots":"Disconnected").append(" | ").append(c.cores()).append(" / ").append(c.threads()).append(" | ").append(c.memory()/1048576).append(" MiB | ").append(c.tiles()).append(" | ").append(String.format(Locale.ROOT,"%.2f ms",c.averageMillis())).append(" | ").append(c.sent()).append(" / ").append(c.received()).append(" bytes\n");computers.setText(text.toString());
            if(job!=null){var contributions=job.contributions();long samples=contributions.stream().mapToLong(DistributedJob.Contribution::samples).sum();double localCpu=contributions.stream().filter(c->c.computer().equals("Master")).mapToDouble(c->c.nanos()/1e9).sum(),remoteCpu=contributions.stream().filter(c->!c.computer().equals("Master")).mapToDouble(c->c.nanos()/1e9).sum();double seconds=job.seconds(),fraction=job.done()/(double)job.total;
                StringBuilder info=new StringBuilder(String.format(Locale.ROOT,"Elapsed: %.2f s · completed: %d / %d (%.2f%%)\nLocal compute: %.2f thread-seconds · remote compute: %.2f thread-seconds\nThroughput: %.0f samples/s · pending in flight: %d\nEstimated remaining: %.2f s\nEstimated local baseline: %.2f s · estimated speedup: %.2f×\nPrecision: %s · generation: %d · escalations: %d\n",seconds,job.done(),job.total,100*fraction,localCpu,remoteCpu,samples/Math.max(.001,seconds),job.inFlight(),fraction>0?seconds*(1-fraction)/fraction:0,job.estimatedLocalSeconds,job.estimatedLocalSeconds/Math.max(.001,seconds),job.context().plan.mode(),job.generation(),job.escalations()));
                Map<String,long[]> groupedStats=new LinkedHashMap<>();for(var c:contributions){long[] totals=groupedStats.computeIfAbsent(server.label(c.computer()),k->new long[2]);totals[0]+=c.tiles();totals[1]+=c.nanos();}
                for(var entry:groupedStats.entrySet()){long[] totals=entry.getValue();info.append(entry.getKey()).append(" · ").append(totals[0]).append(" tiles · ").append(String.format(Locale.ROOT,"%.2f%%",100.*totals[0]/Math.max(1,job.done()))).append(" share · ").append(String.format(Locale.ROOT,"%.2f ms",totals[1]/1e6/Math.max(1,totals[0]))).append(" / tile\n");}
                info.append("Accepted-task occupancy estimate: ").append(String.format(Locale.ROOT,"%.2f%%",100*(localCpu+remoteCpu)/Math.max(.001,seconds*cpu))).append("\n");for(var computer:list)info.append(computer.name()).append(" · noncompute round trip ").append(String.format(Locale.ROOT,"%.2f ms / task",computer.overheadMillis())).append(" (includes scheduling)\n");info.append("Transfer totals TX / RX: ").append(list.stream().mapToLong(MasterServer.Computer::sent).sum()).append(" / ").append(list.stream().mapToLong(MasterServer.Computer::received).sum()).append(" bytes\n");info.append("Connection note: ").append(server.lastError());statistics.setText(info.toString());
                if(System.nanoTime()-lastChart>1_000_000_000L){lastChart=System.nanoTime();double t=(System.nanoTime()-opened)/1e9;Map<String,Long> grouped=new HashMap<>();for(var c:contributions)grouped.merge(server.label(c.computer()),c.samples(),Long::sum);for(var entry:grouped.entrySet()){var line=series.computeIfAbsent(entry.getKey(),name->{var s=new XYChart.Series<Number,Number>();s.setName(name);chart.getData().add(s);return s;});line.getData().add(new XYChart.Data<>(t,entry.getValue()/Math.max(.001,seconds)));while(line.getData().size()>60)line.getData().removeFirst();}}
            }
        }
        if(client==null)workerText.setText("Worker is disconnected.");else{var c=client.status();workerText.setText("Master: "+host.getText()+":"+port.getText()+"\nWorker ID: "+c.id()+"\nStatus: "+c.error()+" · connected slots "+c.slots()+"\nLogical cores / configured threads: "+c.cores()+" / "+c.threads()+"\nCurrent tasks: "+c.tasks()+"\nActive tasks: "+c.active()+" · completed: "+c.tiles()+"\nAverage tile time: "+String.format(Locale.ROOT,"%.2f ms",c.averageMillis())+"\nTotal compute: "+String.format(Locale.ROOT,"%.2f s",c.cpuSeconds())+"\nTransfer TX / RX: "+c.sent()+" / "+c.received()+" bytes · "+String.format(Locale.ROOT,"%.0f bytes/s",(c.sent()+c.received())/Math.max(.001,c.seconds())));}
    }
    private static String addresses(){try{List<String> ips=new ArrayList<>();for(var n:Collections.list(NetworkInterface.getNetworkInterfaces()))if(n.isUp())for(var a:Collections.list(n.getInetAddresses()))if(a instanceof Inet4Address&&!a.isLoopbackAddress())ips.add(a.getHostAddress());return ips.isEmpty()?"127.0.0.1":String.join(", ",ips);}catch(Exception ex){return "See OS network settings";}}
    public void close(){exportCancelled.set(true);timer.stop();operations.shutdown();window.close();}
}
